// Upload form handling and Dropzone configuration

document.addEventListener('DOMContentLoaded', function() {
    const uploadForm = document.getElementById('uploadForm');
    const submitBtn = document.getElementById('submitBtn');
    const fileInput = document.getElementById('audio_file');
    const dropzoneElement = document.getElementById('dropzone');
    const processingModal = new bootstrap.Modal(document.getElementById('processingModal'));

    let selectedFile = null;

    // Configure Dropzone
    Dropzone.autoDiscover = false;

    const dropzone = new Dropzone(dropzoneElement, {
        url: '#', // We'll handle the upload through the form
        autoProcessQueue: false,
        maxFiles: 1,
        acceptedFiles: '.mp3,.wav',
        maxFilesize: 100, // 100MB
        addRemoveLinks: true,
        dictDefaultMessage: `
            <div class="text-center">
                <i class="fas fa-cloud-upload-alt fa-3x text-muted mb-3"></i>
                <h5>Drop your audio file here or click to browse</h5>
                <p class="text-muted mb-0">Supports MP3 and WAV files (max 100MB)</p>
            </div>
        `,
        dictRemoveFile: '<i class="fas fa-trash text-danger"></i>',
        dictCancelUpload: '<i class="fas fa-times text-warning"></i>',
        dictUploadCanceled: 'Upload cancelled',
        dictInvalidFileType: 'Invalid file type. Please upload MP3 or WAV files only.',
        dictFileTooBig: 'File is too large. Maximum size is 100MB.',
        dictMaxFilesExceeded: 'Only one file can be uploaded at a time.',

        init: function() {
            const dz = this;

            // Handle file added
            dz.on('addedfile', function(file) {
                selectedFile = file;
                fileInput.files = createFileList([file]);
                validateForm();

                // Show file info
                showFileInfo(file);
            });

            // Handle file removed
            dz.on('removedfile', function(file) {
                selectedFile = null;
                fileInput.value = '';
                validateForm();
                hideFileInfo();
            });

            // Handle errors
            dz.on('error', function(file, message) {
                console.error('Dropzone error:', message);
                showAlert('error', message);
                dz.removeFile(file);
            });
        }
    });

    // Form validation
    function validateForm() {
        const meetingTitle = document.getElementById('meeting_title').value.trim();
        const hasFile = selectedFile !== null;

        submitBtn.disabled = !(meetingTitle && hasFile);
    }

    // Form input listeners
    document.getElementById('meeting_title').addEventListener('input', validateForm);

    // Form submission
    uploadForm.addEventListener('submit', function(e) {
        e.preventDefault();

        if (!validateForm()) {
            showAlert('error', 'Please fill in all required fields and select an audio file.');
            return;
        }

        // Show processing modal
        processingModal.show();

        // Submit form
        const formData = new FormData(uploadForm);

        fetch(uploadForm.action, {
            method: 'POST',
            body: formData
        })
        .then(response => {
            if (response.redirected) {
                // Handle redirect
                window.location.href = response.url;
            } else {
                return response.text();
            }
        })
        .then(html => {
            if (html) {
                // Handle error response
                processingModal.hide();
                document.body.innerHTML = html;
            }
        })
        .catch(error => {
            console.error('Upload error:', error);
            processingModal.hide();
            showAlert('error', 'An error occurred while uploading the file. Please try again.');
        });
    });

    // Helper functions
    function createFileList(files) {
        const dt = new DataTransfer();
        files.forEach(file => dt.items.add(file));
        return dt.files;
    }

    function showFileInfo(file) {
        hideFileInfo(); // Remove any existing info

        const fileSize = formatFileSize(file.size);
        const fileType = file.type || 'Unknown';

        const infoDiv = document.createElement('div');
        infoDiv.className = 'file-upload-info mt-3';
        infoDiv.id = 'fileInfo';
        infoDiv.innerHTML = `
            <div class="d-flex align-items-center">
                <i class="fas fa-file-audio text-success me-3 fa-2x"></i>
                <div class="flex-grow-1">
                    <h6 class="mb-1">${file.name}</h6>
                    <small class="text-muted">
                        Size: ${fileSize} | Type: ${fileType}
                    </small>
                </div>
                <i class="fas fa-check-circle text-success fa-lg"></i>
            </div>
        `;

        dropzoneElement.parentNode.insertBefore(infoDiv, dropzoneElement.nextSibling);
    }

    function hideFileInfo() {
        const existingInfo = document.getElementById('fileInfo');
        if (existingInfo) {
            existingInfo.remove();
        }
    }

    function formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';

        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));

        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }

    function showAlert(type, message) {
        const alertDiv = document.createElement('div');
        alertDiv.className = `alert alert-${type === 'error' ? 'danger' : 'success'} alert-dismissible fade show`;
        alertDiv.innerHTML = `
            <i class="fas fa-${type === 'error' ? 'exclamation-triangle' : 'check-circle'} me-2"></i>
            ${message}
            <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
        `;

        const container = document.querySelector('.container');
        container.insertBefore(alertDiv, container.firstChild);

        // Auto-dismiss after 5 seconds
        setTimeout(() => {
            if (alertDiv.parentNode) {
                alertDiv.remove();
            }
        }, 5000);
    }

    // File input change listener (fallback)
    fileInput.addEventListener('change', function(e) {
        if (e.target.files.length > 0) {
            const file = e.target.files[0];

            // Validate file type
            const validTypes = ['audio/mpeg', 'audio/wav', 'audio/x-wav'];
            if (!validTypes.includes(file.type) && !file.name.toLowerCase().match(/\.(mp3|wav)$/)) {
                showAlert('error', 'Invalid file type. Please upload MP3 or WAV files only.');
                e.target.value = '';
                return;
            }

            // Validate file size (100MB)
            if (file.size > 100 * 1024 * 1024) {
                showAlert('error', 'File is too large. Maximum size is 100MB.');
                e.target.value = '';
                return;
            }

            selectedFile = file;
            showFileInfo(file);
            validateForm();
        }
    });

    // Initial form validation
    validateForm();
});
